// BUILT BY SB // RUNING ON WEED AND CAFFEINE
// European single-zero roulette. All bet sets are generated by the server;
// the browser may select a key but never provide its payout or covered numbers.
import {createHash,createHmac} from 'node:crypto';

export const ROULETTE_WHEEL=Object.freeze([
 0,32,15,19,4,21,2,25,17,34,6,27,13,36,11,30,8,23,10,5,
 24,16,33,1,20,14,31,9,22,18,29,7,28,12,35,3,26
]);
export const ROULETTE_RED=Object.freeze([
 1,3,5,7,9,12,14,16,18,19,21,23,25,27,30,32,34,36
]);
const reds=new Set(ROULETTE_RED);
export const ROULETTE_BET_MS=30000;
export const ROULETTE_SPIN_MS=8000;
export const ROULETTE_RESULTS_MS=4000;
export const ROULETTE_MIN_CHIP=10;
export const ROULETTE_MAX_CHIP=1000;
export const ROULETTE_MAX_ROUND_STAKE=10000;

const entries=[];
const add=(key,type,label,odds,numbers)=>{
 entries.push(Object.freeze({
  key,type,label,odds,numbers:Object.freeze([...numbers].sort((a,b)=>a-b))
 }));
};
const range=(start,count)=>Array.from({length:count},(_,i)=>start+i);
for(let number=0;number<=36;number++)
 add('number:'+number,'number',String(number),35,[number]);

// A normal table has 12 horizontal streets, three numbers per street.
// Horizontal splits, vertical splits, and 0/1, 0/2, 0/3 zero splits.
for(let r=0;r<12;r++){
 const first=1+r*3;
 for(let col=0;col<2;col++){
  const a=first+col;
  add('split:'+a+'-'+(a+1),'split',a+' / '+(a+1),17,[a,a+1]);
 }
 if(r<11){
  for(let col=0;col<3;col++){
   const a=first+col;
   add('split:'+a+'-'+(a+3),'split',a+' / '+(a+3),17,[a,a+3]);
  }
  for(let col=0;col<2;col++){
   const a=first+col;
   add('corner:'+a+'-'+(a+1)+'-'+(a+3)+'-'+(a+4),'corner',
    a+' / '+(a+1)+' / '+(a+3)+' / '+(a+4),8,[a,a+1,a+3,a+4]);
  }
  add('six:'+first+'-'+(first+5),'six',first+'–'+(first+5),5,range(first,6));
 }
 add('street:'+first,'street',first+'–'+(first+2),11,range(first,3));
}
for(let n=1;n<=3;n++)add('split:0-'+n,'split','0 / '+n,17,[0,n]);
for(let dozen=0;dozen<3;dozen++){
 const start=dozen*12+1;
 add('dozen:'+(dozen+1),'dozen',start+'–'+(start+11),2,range(start,12));
}
for(let column=1;column<=3;column++)
 add('column:'+column,'column','Column '+column,2,
  Array.from({length:12},(_,i)=>i*3+column));
add('color:red','color','Red',1,ROULETTE_RED);
add('color:black','color','Black',1,range(1,36).filter(n=>!reds.has(n)));
add('parity:odd','parity','Odd',1,range(1,36).filter(n=>n%2));
add('parity:even','parity','Even',1,range(1,36).filter(n=>n%2===0));
add('half:low','half','1–18',1,range(1,18));
add('half:high','half','19–36',1,range(19,18));

export const ROULETTE_BETS=Object.freeze(entries);
const byKey=new Map(entries.map(b=>[b.key,b]));
export const rouletteSelection=key=>byKey.get(String(key||''))||null;
export const rouletteColor=number=>number===0?'green':reds.has(number)?'red':'black';
export const roulettePayout=(key,stake,number)=>{
 const bet=rouletteSelection(key);
 if(!bet||!Number.isSafeInteger(stake)||stake<0||!Number.isInteger(number)||number<0||number>36)
  throw new Error('Invalid roulette payout request.');
 return bet.numbers.includes(number)?stake*(bet.odds+1):0;
};
export function rouletteCommitment(seed){
 if(!/^[a-f0-9]{64}$/i.test(String(seed||'')))throw new Error('Invalid roulette seed.');
 return createHash('sha256').update(Buffer.from(seed,'hex')).digest('hex');
}
export function rouletteOutcome(seed,roundId){
 if(!/^[a-f0-9]{64}$/i.test(String(seed||''))||!Number.isSafeInteger(roundId)||roundId<1)
  throw new Error('Invalid roulette verification input.');
 const key=Buffer.from(seed,'hex');
 const limit=0x100000000-(0x100000000%37);
 for(let counter=0;counter<100;counter++){
  const digest=createHmac('sha256',key).update('sb-global-roulette:'+roundId+':'+counter).digest();
  for(let offset=0;offset<=28;offset+=4){
   const value=digest.readUInt32BE(offset);
   if(value<limit)return value%37;
  }
 }
 throw new Error('Roulette rejection sampler exhausted.');
}
